<?php
declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$message='';
if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$action=(string)($_POST['action']??'run_due');if($action==='run_job'){$id=(int)($_POST['job_id']??0);$db->execute('UPDATE scheduled_jobs SET next_run_at=NOW(),enabled=1 WHERE id=?',[$id]);}$result=$scheduler->runDue(100);$message='<pre class="code">'.Web::e(json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre>';}
$scheduler->refreshDiscoveredJobs();$rows='';foreach($db->all('SELECT * FROM scheduled_jobs ORDER BY job_type,job_key')as$j){$rows.='<tr><td><code>'.Web::e($j['job_key']).'</code></td><td>'.Web::e($j['job_type']).'</td><td>'.Web::e($j['schedule_expression']).'</td><td>'.((bool)$j['enabled']?'Tak':'Nie').'</td><td>'.Web::e($j['last_run_at']?:'—').'</td><td>'.Web::e($j['next_run_at']?:'—').'</td><td>'.Web::e($j['last_status']).'</td><td>'.Web::e($j['last_error']?:'—').'</td><td><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="job_id" value="'.(int)$j['id'].'"><button name="action" value="run_job">Uruchom</button></form></td></tr>';}$content='<div class="page-head"><div><h1>Scheduler</h1><p>Automatyczna synchronizacja katalogów/SCIM, housekeeping, delivery, alerty sekretów i rotacja kluczy.</p></div></div>'.$message.'<section class="card"><h2>Uruchamianie produkcyjne</h2><p>Wywołuj daemon co minutę. Blokada MySQL zapobiega równoległemu wykonaniu.</p><pre class="code">* * * * * /usr/bin/php /ścieżka/do/imAuthenticator/bin/scheduler.php</pre><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><button class="primary" name="action" value="run_due">Uruchom teraz zadania oczekujące</button></form></section><div class="table-wrap"><table><thead><tr><th>Klucz</th><th>Typ</th><th>Interwał</th><th>Aktywne</th><th>Ostatnio</th><th>Następnie</th><th>Status</th><th>Błąd</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div>';Web::page('Scheduler',$content,$admin);
